import math

def tau(n):
    if n == 1:
        return 1
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    count = 1
    for exponent in factors.values():
        count *= (exponent + 1)
    return count

def check_k(k):
    lhs = tau(2 * k**3)
    rhs = 2 * k
    return lhs == rhs

solutions = [1, 4, 10]
for k in solutions:
    print(f"Checking k={k}: LHS = {tau(2 * k**3)}, RHS = {2 * k}. Match: {check_k(k)}")

# Verification for a nearby number, e.g., k=2
print(f"Checking k=2: LHS = {tau(2 * 2**3)}, RHS = {2 * 2}. Match: {check_k(2)}")
